def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 3 != 2 or i == len(rows) - 1:
            filtered_rows.append(row)

    if not filtered_rows:
        return []

    rotated_rows = filtered_rows[1:] + [filtered_rows[0]]

    key_value_pairs = {}
    for row in rotated_rows:
        parts = row.split('|')
        if len(parts) == 3:
            key = parts[0]
            try:
                value = int(parts[1])
                status = parts[2]
                if status == 'OK':
                    key_value_pairs[key] = value
            except ValueError:
                pass  # Ignore rows with invalid integer values

    result = []
    for key in sorted(key_value_pairs.keys()):
        result.append([key, key_value_pairs[key]])

    return result

